from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class RepoSnapshot:
    """Read-only repository snapshot.

    v1.0: primarily uses request.repoContext.existingTree (string paths).
    A real read_repo Tool can populate this in future versions.
    """

    file_paths: list[str]


def snapshot_from_existing_tree(existing_tree: list[str]) -> RepoSnapshot:
    normalized: list[str] = []
    for p in existing_tree:
        if not isinstance(p, str):
            continue
        s = p.replace("\\", "/").lstrip("/").strip()
        if s:
            normalized.append(s)
    # de-dup while keeping order
    seen = set()
    out: list[str] = []
    for p in normalized:
        if p in seen:
            continue
        seen.add(p)
        out.append(p)
    return RepoSnapshot(file_paths=out)

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

from jsonschema import Draft202012Validator

from agent_builder_agent.core.schema_store import AGENT_BUILDER_REQUEST_V0, PULL_REQUEST_PROPOSAL_V0


@dataclass(frozen=True)
class ValidationOutcome:
    ok: bool
    errors: list[str]


def schema_validate_request_v0(payload: dict[str, Any]) -> ValidationOutcome:
    v = Draft202012Validator(AGENT_BUILDER_REQUEST_V0)
    errs = sorted(v.iter_errors(payload), key=lambda e: e.path)
    if not errs:
        return ValidationOutcome(ok=True, errors=[])
    return ValidationOutcome(ok=False, errors=[e.message for e in errs][:50])


def schema_validate_proposal_v0(payload: dict[str, Any]) -> ValidationOutcome:
    v = Draft202012Validator(PULL_REQUEST_PROPOSAL_V0)
    errs = sorted(v.iter_errors(payload), key=lambda e: e.path)
    if not errs:
        return ValidationOutcome(ok=True, errors=[])
    return ValidationOutcome(ok=False, errors=[e.message for e in errs][:50])

from agent_builder_agent.core.validators import schema_validate_request_v0


def test_schema_validate_request_minimal_ok():
    payload = {
        "requestId": "req_12345678",
        "specFormat": "json",
        "specObject": {"name": "X", "purpose": "Y"},
        "target": {"repoKind": "single", "language": "python", "framework": "agents-sdk", "runtime": "python311"},
    }
    out = schema_validate_request_v0(payload)
    assert out.ok is True
